{
  "name": "opencode-plugin-vue-devtools",
  "type": "module",
  "version": "0.1.9",
  "description": "OpenCode plugin for Vue DevTools AI Inspect - enables browser-to-agent prompt delivery via local HTTP bridge",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/anthropics/vue-devtools-ai",
    "directory": "packages/opencode-plugin"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "vue",
    "vue-devtools",
    "devtools",
    "ai-inspect",
    "ai",
    "bridge"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "main": "dist/index.js",
  "module": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "README.md",
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org",
    "access": "public"
  },
  "devDependencies": {
    "tsup": "^8.0.0",
    "typescript": "^5.5.0"
  }
}
